n, m = map(int, input().split())

# Dictionary to map first language words to second language words
lang_dict = {}
for _ in range(m):
    a, b = input().split()
    lang_dict[a] = b

# Read lecture words
lecture = input().split()

# Process each word
result = []
for word in lecture:
    # Check if word is in first language
    if word in lang_dict:
        first = word
        second = lang_dict[word]
    else:
        # Find corresponding word in second language
        for key, value in lang_dict.items():
            if value == word:
                first = key
                second = word
                break

    # Choose the shorter word, prefer first if equal
    if len(first) <= len(second):
        result.append(first)
    else:
        result.append(second)

print(' '.join(result))
"}

