n, k = map(int, input().split())
grid = [list(input().strip()) for _ in range(n)]

# Count initially white rows and columns
curr_white_rows = 0
for row in grid:
    if all(cell == 'W' for cell in row):
        curr_white_rows += 1

curr_white_cols = 0
for col in range(n):
    if all(grid[row][col] == 'W' for row in range(n)):
        curr_white_cols += 1

max_white_lines = curr_white_rows + curr_white_cols

# Try all possible erase positions
for i in range(n - k + 1):
    for j in range(n - k + 1):
        # Count rows/columns that become white after erase
        new_white_rows = 0
        new_white_cols = 0

        # Check rows
        for r in range(i, i + k):
            if all(grid[r][c] == 'W' for c in range(n)):
                new_white_rows += 1

        # Check columns
        for c in range(j, j + k):
            if all(grid[r][c] == 'W' for r in range(n)):
                new_white_cols += 1

        # Calculate total white lines after erase
        total = new_white_rows + new_white_cols
        max_white_lines = max(max_white_lines, total)

print(max_white_lines)
"}

