def solve():
    n, m, S_x, S_y = map(int, input().split())

    path = [(S_x, S_y)]

    # Move up to top row at same column
    if S_x > 1:
        path.append((1, S_y))

        # Traverse left to right across top row
        for y in range(S_y - 1, 0, -1):
            path.append((1, y))
        for y in range(S_y + 1, m + 1):
            path.append((1, y))

    # Move down to middle row at same column
    if S_x < n:
        path.append((2, S_y))

        # Traverse left to right across middle row
        for y in range(S_y - 1, 0, -1):
            path.append((2, y))
        for y in range(S_y + 1, m + 1):
            path.append((2, y))

    # Move down to bottom row at same column
    if S_x < n - 1:
        path.append((n, S_y))

        # Traverse right to left across bottom row
        for y in range(S_y - 1, 0, -1):
            path.append((n, y))
        for y in range(S_y + 1, m + 1):
            path.append((n, y))

    # Print the path
    for x, y in path:
        print(x, y)

solve()
