def solve():
    s = input().strip()
    p = input().strip()

    n = len(s)
    m = len(p)

    # dp[i][j][k]: max matches after considering first i chars of s,
    # currently at position j in pattern p, having removed k chars
    dp = [[[-1 for _ in range(n + 1)] for _ in range(m + 1)] for _ in range(n + 1)]
    dp[0][0][0] = 0

    for i in range(n):
        for j in range(m + 1):
            for k in range(n + 1):
                if dp[i][j][k] == -1:
                    continue

                # Option 1: Keep the current character
                if j < m and s[i] == p[j]:
                    new_j = j + 1
                    new_k = k

                    # If we've completed a match, reset and increment count
                    if new_j == m:
                        new_j = 0
                        new_k = k + 1

                    dp[i + 1][new_j][new_k] = max(dp[i + 1][new_j][new_k], dp[i][j][k])

                # Option 2: Remove the current character
                if k < n:
                    new_j = j
                    new_k = k + 1
                    dp[i + 1][new_j][new_k] = max(dp[i + 1][new_j][new_k], dp[i][j][k])

    # For each possible removal count, find the maximum matches
    result = [-1 for _ in range(n + 1)]
    for i in range(n + 1):
        for j in range(m + 1):
            for k in range(n + 1):
                if dp[i][j][k] != -1:
                    result[k] = max(result[k], dp[i][j][k])

    print(' '.join(map(str, result)))

solve()
