    n = len(s)
    vowels = {'I', 'E', 'A', 'O', 'U', 'Y'}

    # Brute force approach
    total = 0.0
    for i in range(n):
        for j in range(i, n):
            length = j - i + 1
            vowel_count = sum(1 for k in range(i, j + 1) if s[k] in vowels)
            contribution = vowel_count / length
            total += contribution

    print(f"{total:.8f}")

