def contains_all_substrings(s: str, k: int) -> bool:
    """Check if all binary strings of length k appear as substrings in s."""
    # Get all binary strings of length k
    all_substrings = {bin(i)[2:].zfill(k) for i in range(2 ** k)}

    # Get all substrings of length k in s
    substrings = {s[i:i+k] for i in range(len(s) - k + 1)}

    return substrings == all_substrings


def max_k(s: str) -> int:
    """Find the maximum k such that all binary strings of length k appear in s."""
    # Check k from 0 up to len(s)
    for k in range(len(s) + 1):
        # Check if all possible binary strings of length k appear
        if contains_all_substrings(s, k):
            return k
    return 0


def main():
    n = int(input())
    strings = []

    for _ in range(n):
        strings.append(input().strip())

    m = int(input())

    # Store all strings (initial + operations)
    all_strings = strings.copy()

    for op_num in range(1, m + 1):
        a, b = map(int, input().split())

        # Concatenate strings a-1 and b-1
        new_string = all_strings[a - 1] + all_strings[b - 1]

        # Add new string to all_strings
        all_strings.append(new_string)

        # Calculate and print max k
        print(max_k(new_string))

if __name__ == "__main__":
    main()
