        for i in range(n - 1):
            v = int(next(it))
            u = int(next(it))
            w = int(next(it))
            edges[v].append((u, w))
            edges[u].append((v, w))

        # Find leaves
        leaves = []
        visited = [False] * (n + 1)

        def dfs(v, parent):
            visited[v] = True
            is_leaf = True
            for u, w in edges[v]:
                if u != parent:
                    is_leaf = False
                    dfs(u, v)
            if is_leaf:
                leaves.append(v)

        dfs(1, -1)

        # Build tree and calculate subtree sizes
        tree = [[] for _ in range(n + 1)]
        for v in range(1, n + 1):
            for u, w in edges[v]:
                if u != (v - 1 if v != 1 else -1):  # Find parent
                    tree[v].append((u, w))

