import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    q = int(next(it))

    # Track which notifications have been read (by type 1 event index)
    read_positions = [False] * (q + 1)  # 1-indexed
    app_for_position = [0] * (q + 1)  # Track which app each notification belongs to

    out_lines = []

    for event_num in range(1, q + 1):
        type_event = int(next(it))

        if type_event == 1:
            x = int(next(it))
            # This is a notification event
            read_positions[event_num] = False
            app_for_position[event_num] = x
        elif type_event == 2:
            x = int(next(it))
            # Read all notifications for this app
            # We need to mark all notifications from this app as read
            # But we need to know which ones are unread first
            for pos in range(1, event_num):
                if app_for_position[pos] == x and not read_positions[pos]:
                    read_positions[pos] = True
        elif type_event == 3:
            t = int(next(it))
            # Read first t notifications (positions 1 to t)
            for pos in range(1, t + 1):
                if not read_positions[pos]:
                    read_positions[pos] = True

        # Count unread notifications
        unread = 0
        for pos in range(1, event_num + 1):
            if not read_positions[pos]:
                unread += 1
        out_lines.append(str(unread))

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    main()
