def game_state(line, m, k):
    """Return a tuple representing the game state for a line."""
    g_pos = line.find('G')
    r_pos = line.find('R')

    # Count number of soldiers
    num_soldiers = line.count('G') + line.count('R')

    if num_soldiers == 0:
        return (0, 0)  # No soldiers, no moves
    elif num_soldiers == 1:
        # Single soldier
        soldier_pos = g_pos if g_pos != -1 else r_pos
        # Number of positions the soldier can move to
        max_reach = m - 1  # Can move to any position from 0 to m-1
        # But they can't stay in place, so they can move to max_reach positions
        return (soldier_pos, max_reach, m, k)  # State, max_reach, m, k
    else:
        # Two soldiers, opposite colors
        # They must be at positions g_pos and r_pos
        # Calculate the distance between them
        dist = abs(g_pos - r_pos)

        # If they're adjacent
        if dist == 1:
            return (g_pos, r_pos, m, k)  # Adjacent
        else:
            # Separated by some distance
            # Left soldier at min(g_pos, r_pos)
            left_pos = min(g_pos, r_pos)
            right_pos = max(g_pos, r_pos)
            dist = right_pos - left_pos

            # If the left soldier is G
            if g_pos < r_pos:
                return (g_pos, r_pos, m, k, "G_left")
            # If the left soldier is R
            else:
                return (g_pos, r_pos, m, k, "R_left")

# Memoization dictionary for winning positions
winning = {}

def is_winning(state):
    """Return True if the current player can force a win from this state."""
    # If we've computed this state before
    if state in winning:
        return winning[state]

    # Parse the state
    if state[0] == 0:
        # No soldiers
        winning[state] = False
        return False

    # Single soldier
    if len(state) == 3:
        soldier_pos, max_reach, m, k = state
        for move in range(1, k + 1):
            new_pos = soldier_pos + move if soldier_pos < m - 1 else soldier_pos - move
            new_state = (new_pos, max_reach, m, k)
            if not is_winning(new_state):
                winning[state] = True
                return True
        winning[state] = False
        return False

    # Two soldiers
    if len(state) == 4:
        left_pos, right_pos, m, k = state
        for move_left in range(1, k + 1):
            new_left = left_pos + move_left if left_pos < m - 1 else left_pos - move_left
            new_state = (new_left, right_pos, m, k)
            if not is_winning(new_state):
                winning[state] = True
                return True
        winning[state] = False
        return False

    # Two soldiers separated with orientation
    if len(state) == 5:
        g_pos, r_pos, m, k, orientation = state
        if orientation == "G_left":
            for move_left in range(1, k + 1):
                new_g = g_pos + move_left if g_pos < m - 1 else g_pos - move_left
                new_state = (new_g, r_pos, m, k, orientation)
                if not is_winning(new_state):
                    winning[state] = True
                    return True
            winning[state] = False
            return False
        else:  # R_left
            for move_left in range(1, k + 1):
                new_r = g_pos + move_left if g_pos < m - 1 else g_pos - move_left
                new_state = (new_r, r_pos, m, k, orientation)
                if not is_winning(new_state):
                    winning[state] = True
                    return True
            winning[state] = False
            return False

    raise ValueError("Unknown state format")

