    a = list(map(int, input().split()))

    # dp[i] = maximum length of contest ending with problem i
    dp = [1] * n

    for i in range(n):
        # Find all j < i such that a[i] <= 2 * a[j]
        left = 0
        right = i - 1
        while left < right:
            mid = (left + right + 1) // 2
            if a[mid] >= a[i] / 2:
                left = mid
            else:
                right = mid - 1

        # All j from left to i-1 satisfy a[j] >= a[i]/2
        # But we also need a[j] <= a[i] (since array is sorted)
        # So all j in [left, i-1]

        # Find the maximum dp in this range
        max_val = 0
        for j in range(left, i):
            if a[j] >= a[i] / 2:
                max_val = max(max_val, dp[j])

        if max_val > 0:
            dp[i] = max_val + 1

