    a = list(map(int, data[1:1+n]))

    # Find LIS length using patience sorting
    lis = []
    for num in a:
        # Find the first index in lis >= num
        low, high = 0, len(lis)
        while low < high:
            mid = (low + high) // 2
            if lis[mid] < num:
                low = mid + 1
            else:
                high = mid
        if low == len(lis):
            lis.append(num)
    lis_length = len(lis)

    # Find left[i]: length of LIS ending at a[i]
    left = [1] * n
    for i in range(n):
        for j in range(i):
            if a[i] > a[j] and left[i] < left[j] + 1:
                left[i] = left[j] + 1

    # Find right[i]: length of LIS starting at a[i]
    right = [1] * n
    for i in range(n-1, -1, -1):
        for j in range(i+1, n):
            if a[j] > a[i] and right[i] < right[j] + 1:
                right[i] = right[j] + 1

    # Categorize
    result = []
    for i in range(n):
        total = left[i] + right[i] - 1
        if total > lis_length:
            result.append('1')  # Group 1: not in any LIS
        elif total == lis_length:
            result.append('2')  # Group 2: in some but not all LIS
        else:
            result.append('3')  # Group 3: in every LIS

    print(''.join(result))

