def count_lucky_digits(n):
    """Count the number of lucky digits (4 or 7) in n."""
    return sum(1 for digit in str(n) if digit in '47')


def get_pattern(start, length):
    """Get the pattern of lucky digit counts for the interval [start, start+length-1]."""
    return [count_lucky_digits(start + i) for i in range(length)]


def find_b(a, l):
    """Find the minimum b > a such that the pattern matches."""
    target_pattern = get_pattern(a, l)

    # Brute force search for b
    b = a + 1
    while True:
        current_pattern = get_pattern(b, l)
        if current_pattern == target_pattern:
            return b
        b += 1


def main():
    a, l = map(int, input().split())
    print(find_b(a, l))

if __name__ == "__main__":
    main()
"}

