def solve():
    n, x = map(int, input().split())
    a = list(map(int, input().split()))

    # Build chains by following from each beaver
    chains = []
    visited = set()

    for i in range(n):
        if i not in visited:
            chain = []
            current = i
            while current is not None:
                if current in visited:
                    break
                visited.add(current)
                chain.append(current)
                current = a[current] if a[current] != 0 else None
            if chain:
                chains.append(chain)

    # Find all possible positions for x
    positions = set()

    for chain in chains:
        # This chain is: chain[0] -> chain[1] -> ... -> chain[-1]

        # Check if x is already in this chain
        if x in chain:
            # x is already in this chain, we can only insert at the end
            # or at the beginning if it's the first element
            if chain[0] == x:
                positions.add(1)  # x is at the beginning of the chain
            elif chain[-1] == x:
                positions.add(len(chain) + 1)  # x is at the end of the chain
            else:
                # x is somewhere in the middle, we can only insert at the end
                positions.add(len(chain) + 1)
        else:
            # x is not in this chain, we can insert it at any position
            for i in range(len(chain) + 2):
                positions.add(i + 1)

    # Output all positions in increasing order
    for p in sorted(positions):
        print(p)

solve()

