from collections import defaultdict, deque

def solve():
    t = int(input())
    for _ in range(t):
        # Skip empty line
        while True:
            line = input().strip()
            if line:
                break

        n, m = map(int, input().split())
        edges = defaultdict(list)
        for _ in range(m):
            a, b = map(int, input().split())
            edges[a].append(b)

        # Track number of paths to each vertex
        paths = [0] * (n + 1)
        paths[1] = 1

        # Track if vertex has infinite paths
        infinite = [False] * (n + 1)

        # BFS
        queue = deque([1])
        visited = set([1])

        while queue:
            u = queue.popleft()

            for v in edges[u]:
                # If v has infinite paths, then all paths to v are infinite
                if infinite[v]:
                    infinite[u] = True
                    continue

                # If v has been reached, we have multiple paths
                if paths[v] > 0:
                    infinite[v] = True
                else:
                    paths[v] += 1
                    queue.append(v)

        # Output results
        result = []
        for i in range(1, n + 1):
            if infinite[i]:
                result.append("-1")
            elif paths[i] == 1:
                result.append("1")
            elif paths[i] > 1:
                result.append("2")
            else:
                result.append("0")

        print(" ".join(result))

solve()
