def are_equivalent(a, b):
    """Check if strings a and b are equivalent."""
    # Base case: strings are equal
    if a == b:
        return True

    # If lengths are not even, cannot split
    if len(a) % 2 != 0:
        return False

    # Split into two halves
    mid = len(a) // 2
    a1, a2 = a[:mid], a[mid:]
    b1, b2 = b[:mid], b[mid:]

    # Check both possibilities
    return (are_equivalent(a1, b1) and are_equivalent(a2, b2)) or \
           (are_equivalent(a1, b2) and are_equivalent(a2, b1))

