import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    k = int(data[1])
    a = list(map(int, data[2:2+n]))

    # Sort the array
    a.sort()

    # Sliding window approach
    left = 0
    max_count = 0
    target = 0

    for right in range(n):
        # Cost to make all elements in window equal to a[right]
        # cost = sum_{i=left}^{right-1} (a[right] - a[i])

        # If window is size 1, cost is 0
        if right == left:
            cost = 0
        else:
            cost = (right - left) * a[right] - sum(a[left:right])

        while cost > k:
            left += 1
            if left == right:
                cost = 0
            else:
                cost = (right - left) * a[right] - sum(a[left:right])

        # Update answer
        if right - left + 1 > max_count:
            max_count = right - left + 1
            target = a[right]
        elif right - left + 1 == max_count and a[right] < target:
            target = a[right]

    print(f"{max_count} {target}")

if __name__ == "__main__":
    solve()
