import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    grid = []
    for _ in range(n):
        row = [int(next(it)) for _ in range(m)]
        grid.append(row)

    # Count single cells
    total = n * m

    # Count row multi-cell sets
    for row in grid:
        count0 = row.count(0)
        count1 = row.count(1)

        # For each color, count multi-cell sets
        if count0 >= 2:
            total += (1 << count0) - count0 - 1  # 2^count0 - count0 - 1
        if count1 >= 2:
            total += (1 << count1) - count1 - 1

    # Count column multi-cell sets
    for col in range(m):
        count0 = 0
        count1 = 0
        for row in range(n):
            cell = grid[row][col]
            if cell == 0:
                count0 += 1
            else:
                count1 += 1

        if count0 >= 2:
            total += (1 << count0) - count0 - 1
        if count1 >= 2:
            total += (1 << count1) - count1 - 1

    print(total)

