import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    it = iter(data)
    t = int(next(it))

    out_lines = []

    for _ in range(t):
        # Skip empty line
        while True:
            if not data:
                break
            token = next(it, None)
            if token is None:
                break
            if token.strip() == "":
                continue
            if token.isdigit():
                break

        # Read n and m
        n = int(next(it))
        m = int(next(it))

        # Read edges
        adj = [[] for _ in range(n + 1)]
        for _ in range(m):
            a = int(next(it))
            b = int(next(it))
            adj[a].append(b)

        # Find all vertices reachable from 1
        reachable = [False] * (n + 1)
        reachable[1] = True
        q = [1]
        while q:
            u = q.pop()
            for v in adj[u]:
                if not reachable[v]:
                    reachable[v] = True
                    q.append(v)

        # Build reversed graph for topological sort
        rev_adj = [[] for _ in range(n + 1)]
        for u in range(1, n + 1):
            for v in adj[u]:
                rev_adj[v].append(u)

        # Topological sort
        in_degree = [0] * (n + 1)
        for u in range(1, n + 1):
            for v in adj[u]:
                in_degree[v] += 1

        topo_order = []
        q = [u for u in range(1, n + 1) if reachable[u] and in_degree[u] == 0]
        while q:
            u = q.pop()
            topo_order.append(u)
            for v in rev_adj[u]:
                in_degree[v] -= 1
                if in_degree[v] == 0:
                    q.append(v)

        # Check if any vertex has in-degree > 0 after topological sort - this means there's a cycle
        cycle = [False] * (n + 1)
        for u in range(1, n + 1):
            if reachable[u] and in_degree[u] > 0:
                cycle[u] = True

        # Count paths from 1 to each vertex
        dp = [0] * (n + 1)
        dp[1] = 1
        for u in topo_order:
            for v in adj[u]:
                dp[v] += dp[u]

        # Prepare answer
        answer = []
        for v in range(1, n + 1):
            if not reachable[v]:
                answer.append("0")
            elif cycle[v]:
                answer.append("-1")
            elif dp[v] == 1:
                answer.append("1")
