p = input().strip()

n, m = len(s), len(p)

# dp[i][j]: maximum number of occurrences of p we can get by considering first i characters of s
# and having j characters removed

def solve(s, p):
    n, m = len(s), len(p)

    # dp[i][j]: max occurrences with first i chars considered and j removed
    dp = [[-1] * (n + 1) for _ in range(n + 1)]
    dp[0][0] = 0

    for i in range(n):
        for j in range(i + 1):
            if dp[i][j] == -1:
                continue

            # Option 1: keep the i-th character
            if dp[i+1][j] < dp[i][j]:
                dp[i+1][j] = dp[i][j]

            # Option 2: remove the i-th character
            if dp[i+1][j+1] < dp[i][j]:
                dp[i+1][j+1] = dp[i][j]

            # Option 3: try to match p starting at i-th character (if it helps)
            if dp[i][j] != -1 and i + m <= n:
                chars_needed = 0
                k = 0
                while k < m:
                    if s[i + k] == p[k]:
                        k += 1
                    else:
                        chars_needed += 1
                        k = 0
                if i + k <= n:
                    # We can match p starting at i with chars_needed removals
                    if j + chars_needed <= n:
                        dp[i+k][j+chars_needed] = max(dp[i+k][j+chars_needed], dp[i][j] + 1)

    # Now compute answer for each x
    result = []
    for x in range(n + 1):
        max_k = 0
        for k in range(len(dp[-1])):
            if dp[n][k] != -1 and k <= x:
                max_k = k
            else:
                break
        result.append(str(max_k))

    return ' '.join(result)

print(solve(s, p))
"}

