import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    m = int(data[0])
    A = list(map(int, data[1:m+1]))
    B = list(map(int, data[m+1:2*m+1]))

    # Calculate F(n, k) for small values
    def comb(n, k):
        if k > n or k < 0:
            return 0
        if k == 0 or k == n:
            return 1
        if k > n - k:
            k = n - k
        result = 1
        for i in range(k):
            result = result * (n - i) // (i + 1)
        return result

    def f(n, k):
        if k > n:
            return 0
        total = 0
        for x in range(1, n - k + 2):
            total += x * comb(n - x, k - 1)
        return total / comb(n, k)

    # Sort B in ascending order
    B_sorted = sorted(B)

    # Sort A in ascending order
    A_sorted = sorted(A)

    # Pair smallest A with smallest B, etc.
    result = []
    for a, b in zip(A_sorted, B_sorted):
        result.append(str(a))

    sys.stdout.write(" ".join(result))

if __name__ == "__main__":
    solve()
