def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    s = data[0]
    n = len(s)

    m = int(data[1])
    queries = []

    idx = 2
    for _ in range(m):
        l = int(data[idx])
        r = int(data[idx + 1])
        queries.append((l - 1, r - 1))  # convert to 0-indexed
        idx += 2


    def has_non_bad_substring(substring):
        # Check if there's any three-character substring that is NOT one of the three bad strings
        bad_strings = {"zyx", "xzy", "yxz"}
        len_sub = len(substring)

        if len_sub < 3:
            return True  # No three-character substring, algorithm terminates immediately

        # Check all consecutive three-character substrings
        for i in range(len_sub - 2):
            triplet = substring[i:i+3]
            if triplet not in bad_strings:
                return True

        return False


    results = []
    for l, r in queries:
        substring = s[l:r+1]
        if has_non_bad_substring(substring):
            results.append("YES")
        else:
            results.append("NO")

    print("\n".join(results))

