import sys

import math

def solve():
    k = int(sys.stdin.readline())
    s = sys.stdin.readline().strip()
    q = int(sys.stdin.readline())
    queries = [sys.stdin.readline().split() for _ in range(q)]

    total_teams = 2 ** k
    total_games = total_teams - 1

    # Build the tournament structure
    def build_tournament():
        # Tree structure: games[game] = [winner1, winner2] (the two teams that won the previous round)
        # We'll build it from bottom to top
        games = [None] * (total_teams + total_games + 1)

        # First round: games 1 to 2^{k-1}
        for i in range(1, total_games + 1):
            if i <= total_games // 2:
                # Game i has teams (2i-1, 2i)
                winner1, winner2 = 2 * i - 1, 2 * i
                if s[i - 1] == '0':
                    winner = winner1
                elif s[i - 1] == '1':
                    winner = winner2
                else:
                    winner = [winner1, winner2]
                games[i] = winner
            else:
                # This is a later round
                pass

        # Subsequent rounds
        for depth in range(2, k + 1):
            for i in range(1, total_games + 1):
                if i <= total_games // (2 ** depth - 1):
                    # Game i has children 2i-1 and 2i
                    if games[2 * i - 1] == games[2 * i]:
                        # Both children have the same winner
                        games[i] = games[2 * i - 1]
                    else:
                        # Different winners, determine based on game result
                        if s[i - 1] == '0':
                            games[i] = games[2 * i - 1]
                        elif s[i - 1] == '1':
                            games[i] = games[2 * i]
                        else:
                            games[i] = games[2 * i - 1].copy()
                            games[i].extend(games[2 * i])

        return games

    # Process queries
    for p, c in queries:
        p_idx = int(p) - 1
        s = s[:p_idx] + c + s[p_idx+1:]
        games = build_tournament()
        # The champion is games[1]
        print(len(games[1]))

solve()
