    queries = [sys.stdin.readline().split() for _ in range(q)]

    n = 2 ** k
    total_games = n - 1

    # Build the tournament tree
    class SegmentTree:
        def __init__(self, data):
            self.n = n
            self.size = 1
            while self.size < self.n:
                self.size <<= 1
            self.tree = [set(range(self.n)) for _ in range(self.size)]

            # Build the tree
            for i in range(self.n):
                self.tree[self.size + i] = {i}

            for i in range(self.size - 1, 0, -1):
                if s[i - 1] == '0':
                    self.tree[i] = self.tree[2 * i].copy()
                elif s[i - 1] == '1':
                    self.tree[i] = self.tree[2 * i + 1].copy()
                else:
                    self.tree[i] = self.tree[2 * i].copy()
                    self.tree[i].update(self.tree[2 * i + 1])

        def update(self, pos, value):
            pos += self.size
            self.tree[pos] = {value}
            pos >>= 1
            while pos >= 1:
                if s[pos - 1] == '0':
                    self.tree[pos] = self.tree[2 * pos].copy()
                elif s[pos - 1] == '1':
                    self.tree[pos] = self.tree[2 * pos + 1].copy()
                else:
                    self.tree[pos] = self.tree[2 * pos].copy()
                    self.tree[pos].update(self.tree[2 * pos + 1])
