def solve():
    import sys
    input = sys.stdin.read().split()
    data = iter(input)

    t = int(next(data))

    for _ in range(t):
        n = int(next(data))
        m = int(next(data))

        # Build adjacency list
        adj = [[] for _ in range(n + 1)]
        for _ in range(m):
            u = int(next(data))
            v = int(next(data))
            adj[u].append(v)
            adj[v].append(u)

        # Find a bipartition using BFS
        color = [-1] * (n + 1)
        is_bipartite = True

        for start in range(1, n + 1):
            if color[start] == -1:
                queue = [start]
                color[start] = 0

                while queue:
                    u = queue.pop(0)
                    for v in adj[u]:
                        if color[v] == -1:
                            color[v] = color[u] ^ 1
                            queue.append(v)
                        elif color[v] == color[u]:
                            # Not bipartite
                            is_bipartite = False
                            break
                    if not is_bipartite:
                        break
                if not is_bipartite:
                    break

        if is_bipartite:
            # Select the first partition
            partition0 = [i for i in range(1, n + 1) if color[i] == 0]
            partition1 = [i for i in range(1, n + 1) if color[i] == 1]

            # Pick the partition that comes first
            if len(partition0) <= len(partition1):
                chosen = partition0
            else:
                chosen = partition1
        else:
            # Graph is not bipartite, try to find a dominating set
            # Pick all vertices from one partition
            # But need to ensure size <= n//2
            partition0 = [i for i in range(1, n + 1) if color[i] == 0]
            partition1 = [i for i in range(1, n + 1) if color[i] == 1]

            if len(partition0) <= len(partition1):
                chosen = partition0
            else:
                chosen = partition1

        # Print output with trailing space for the first line
        print(len(chosen))
        if len(chosen) > 0:
            print(' '.join(map(str, chosen)) + ' ')  # Add trailing space
        else:
            print()

solve()
