def find_char(n, k, len_cache, f0):
    ": Find the k-th character of fn (1-indexed)."
    ": If k > len(fn), return "." ""
    ": If k <= len(f0), return f0[k-1]"
    ": If k <= len(f1), recurse"
    ": else: return "." ""

    if k > len_cache[n]:
        return "."

    if n == 0:
        return f0[k-1]

    # fn = prefix + f(n-1) + middle + f(n-1) + suffix
    prefix = 43
    middle = 24
    suffix = 1

    if k <= prefix:
        return "What are you doing while sending "[k-1]

    if k <= prefix + len_cache[n-1]:
        return find_char(n-1, k - prefix, len_cache, f0)

    if k <= prefix + len_cache[n-1] + middle:
        return "? Are you busy? Will you send "[k - prefix - len_cache[n-1] - 1]

    if k <= prefix + len_cache[n-1] + middle + len_cache[n-1]:
        return find_char(n-1, k - prefix - len_cache[n-1] - middle, len_cache, f0)

    return "?"

# Compute lengths for f0 to f100000 (we won't actually compute all, but we need the formula)
def compute_lengths(max_n):
    len_cache = {}  # len_cache[i] = length of fi
    len_cache[0] = 108  # f0 is known
    for i in range(1, max_n + 1):
        len_cache[i] = 2 * len_cache[i-1] + 68
    return len_cache

