def has_win(board, n):
    """Check if there's a winning configuration"""
    for i in range(n):
        # Check rows
        for j in range(n-2):
            if board[i][j] == board[i][j+1] == board[i][j+2]:
                return i, j, i, j+1, i, j+2  # return positions of the winning line
        # Check columns
        for j in range(n-2):
            if board[j][i] == board[j+1][i] == board[j+2][i]:
                return j, i, j+1, i, j+2, i  # return positions of the winning line
    return None


def flip(board, i, j):
    """Flip token at position (i, j)"""
    board[i][j] = 'X' if board[i][j] == 'O' else 'O'


def solve():
    t = int(input())
    for _ in range(t):
        n = int(input())
        board = []
        for _ in range(n):
            row = list(input())
            board.append(row)

        while True:
            win_info = has_win(board, n)
            if win_info is None:
                break
            # Flip the middle token of the winning line
            # win_info format: (i, j, i, j, i, j) for row or column
            # For a row: (i, j, i, j+1, i, j+2)
            # For a column: (j, i, j+1, i, j+2, i)
            if win_info[0] == win_info[2]:  # it's a row
                flip(board, win_info[1], win_info[1])  # middle of row
            else:  # it's a column
                flip(board, win_info[1], win_info[1])  # middle of column

        for row in board:
            print(''.join(row))

solve()
