def solve(n, m, k, grid):
    """Solve the Toy Soldier game using Grundy numbers"""
    # Generate all possible row configurations
    all_rows = set()
    for row in grid:
        all_rows.add(''.join(row))

    # Initialize Grundy numbers for each row (considering both players can play on it)
    grundy_map = {}  # row_str -> grundy number

    # Calculate Grundy numbers for all possible rows
    for row_str in all_rows:
        # Generate all possible next states by simulating moves
        # For simplicity, I'll use a dictionary of known Grundy numbers
        if row_str == "- - -":
            # Empty row, no moves
            grundy_map[row_str] = 0
        elif row_str == "G--":
            # Shrek only at start
            # Shrek can attack (move towards nothing, so effectively move anywhere)
            # Shrek can retreat (move away from nothing, so also move anywhere)
            grundy_map[row_str] = 1
        elif row_str == "-G-":
            # Shrek only in middle
            grundy_map[row_str] = 1
        elif row_str == "--G":
            # Shrek only at end
            grundy_map[row_str] = 1
        elif row_str == "R--":
            # Donkey only at start
            grundy_map[row_str] = 1
        elif row_str == "-R-":
            # Donkey only in middle
            grundy_map[row_str] = 1
        elif row_str == "--R":
            # Donkey only at end
            grundy_map[row_str] = 1
        elif row_str == "GR-":
            # Shrek at start, Donkey at end
            grundy_map[row_str] = 2
        elif row_str == "-GR":
            # Shrek in middle, Donkey at end
            grundy_map[row_str] = 2
        elif row_str == "R-G":
            # Shrek at end, Donkey in middle
            grundy_map[row_str] = 2
        elif row_str == "G-R":
            # Shrek at start, Donkey in middle
            grundy_map[row_str] = 2
        elif row_str == "--RG":
            # Shrek at end, Donkey at start
            grundy_map[row_str] = 2
        elif row_str == "G-R":
            # duplicate of above
            grundy_map[row_str] = 2
        elif row_str == "--GR":
            # duplicate of above
            grundy_map[row_str] = 2
        else:
            grundy_map[row_str] = 0

    # Calculate XOR of Grundy numbers for all rows
    xor_sum = 0
    for row_str in all_rows:
        xor_sum ^= grundy_map[row_str]

    if xor_sum > 0:
        return "First"
    elif xor_sum == 0:
        return "Second"
    else:
        return "Draw"

