def solve(n, m, k, grid):
    """Solve the Toy Soldier game using Grundy numbers"""
    # Map from row configuration to Grundy number
    # Grundy numbers for rows with only 'G'
    grundy_map_shrek = {
        "G--": 0,  # Shrek at start
        "-G-": 1,  # Shrek in middle
        "--G": 0   # Shrek at end
    }

    # Grundy numbers for rows with only 'R'
    grundy_map_donkey = {
        "R--": 0,  # Donkey at start
        "-R-": 1,  # Donkey in middle
        "--R": 0   # Donkey at end
    }

    # Grundy numbers for rows with both 'G' and 'R'
    grundy_map_both = {
        "GR-": 0,  # Shrek at start, Donkey at end
        "-GR": 0,  # Shrek in middle, Donkey at end
        "R-G": 0,  # Shrek at end, Donkey in middle
        "G-R": 1,  # Shrek at start, Donkey in middle
        "--RG": 1, # Shrek at end, Donkey at start
    }

    # Calculate XOR of Grundy numbers for all rows
    xor_sum = 0
    for row in grid:
        row_str = ''.join(row)

        if 'G' in row_str and 'R' in row_str:
            # Both have moves
            # Try to find the key in the map
            if row_str in grundy_map_both:
                xor_sum ^= grundy_map_both[row_str]
            else:
                # Default to 0 if not found (shouldn't happen)
                xor_sum ^= 0
        elif 'G' in row_str:
            # Shrek only
            xor_sum ^= grundy_map_shrek.get(row_str, 0)
        elif 'R' in row_str:
            # Donkey only
            xor_sum ^= grundy_map_donkey.get(row_str, 0)
        else:
            # Empty row
            pass

    if xor_sum > 0:
        return "First"
    elif xor_sum == 0:
