        has_loop = [False] * (n + 1)

        for _ in range(m):
            a = int(data[ptr])
            b = int(data[ptr + 1])
            ptr += 2
            adj[a].append(b)
            if a == b:
                has_loop[b] = True

        # Find all vertices reachable from 1
        reachable = set()
        visited = [False] * (n + 1)
        queue = deque([1])
        visited[1] = True

        while queue:
            u = queue.popleft()
            reachable.add(u)
            for v in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    queue.append(v)

        # Count paths to each vertex (only for reachable vertices without loops)
        path_count = [0] * (n + 1)

