        # Find vertices with no incoming edges (indegree 0)
        indegree = [0] * (n + 1)
        for u in reachable:
            for v in adj[u]:
                indegree[v] += 1

        # Process vertices in topological order
        topo_order = []
        in_queue = [False] * (n + 1)
        queue = deque()
