    scientists = []
    for i in range(n):
        ki, a1, x, y, m = map(int, input().split())
        seq = generate_sequence(ki, a1, x, y, m)
        scientists.append(seq)

    # Use min-heap to always pick smallest available
    heap = []
    for i in range(n):
        if scientists[i]:
            heapq.heappush(heap, (scientists[i][0], i, 0))

    result = []
    bad_pairs = 0
    total_problems = sum(len(seq) for seq in scientists)

