def solve():
    n, x = map(int, input().split())
    a = list(map(int, input().split()))

    # Build adjacency list
    from collections import defaultdict
    adj = defaultdict(list)
    for i in range(n):
        if a[i] != 0:
            adj[a[i]].append(i + 1)  # i is 0-indexed, beavers are 1-indexed

    result = set()

    # Try each beaver as a potential starting point
    for start in range(1, n + 1):
        # Build chain from start
        chain = []
        current = start
        while current is not None:
            chain.append(current)
            # Find the next beaver
            for next_beaver in adj[current]:
                current = next_beaver
                break
            else:
                # No next beaver
                current = None

        # Count length of chain
        chain_length = len(chain)

        # Check if Smart Beaver (x) is in this chain
        if x in chain:
            # Can be at any position within the chain
            for pos in range(chain_length):
                result.add(pos + 1)  # positions are 1-indexed
        else:
            # Can be after the chain ends
            result.add(chain_length + 1)

    # Sort and print results
    for pos in sorted(result):
        print(pos)

