            g_pos = positions['G']
            r_pos = positions['R']
            distance = abs(g_pos - r_pos)

            # For distance 0 (same position, not possible since each line has at most 2 soldiers)
            if distance == 0:
                grundy = 0
            # For distance 1: Grundy = 0
            elif distance == 1:
                grundy = 0
            # For distance >= 2: Alternate between 1 and 0
            else:
