        elif 'G' in positions:
            # Only Shrek's soldier
            grundy = 1
        elif 'R' in positions:
            # Only Donkey's soldier
            grundy = 1
        else:
            # No soldiers
            grundy = 0

        total ^= grundy

    # Determine winner
    if total == 0:
        # First player loses
        return "Second"
    else:
        # First player wins
        return "First"

