    # Try each possible click position
    for i in range(n - k + 1):
        for j in range(n - k + 1):
            # Check which rows become all white
            white_rows = 0
            for r in range(n):
                # Check if all black cells in row r are within the k x k square
                # The square covers columns j to j+k-1
                all_white = True
                for col in row_black_cols[r]:
                    if not (j <= col <= j + k - 1):
                        all_white = False
