def extended_gcd(a, b):
    if b == 0:
        return a, 1, 0
    else:
        g, x, y = extended_gcd(b, a % b)
        return g, y, x - (a // b) * y

def crt(n, a, m, b):
    """Solve x ≡ a (mod n), x ≡ b (mod m)"""
    g, x, y = extended_gcd(n, m)

    # Check if solution exists
    if (b - a) % g != 0:
        return None

    lcm = n * m // g
    # Find the smallest non-negative solution
    x0 = (a + (m // g) * ((b - a) // g) * x) % lcm
    return x0

def solve():
    n, m, k = map(int, input().split())
    a = list(map(int, input().split()))
    b = list(map(int, input().split()))

    # Binary search on D (day number)
    def count_up_to(D):
        # Count how many days up to day D have different colors
        # Days are 0-indexed
        lcm = n * m // extended_gcd(n, m)[0]
        total = 0

        for x in range(n):
            for y in range(m):
                if a[x] != b[y]:
                    i0 = crt(n, x, m, y)
                    if i0 is None:
                        continue

                    # Count days i where i0 <= i <= D and i ≡ x (mod n), i ≡ y (mod m)
                    # These are i = i0 + t*lcm for t >= 0
                    if i0 <= D:
                        # Number of such days
                        count = (D - i0) // lcm + 1
                        total += count
                    else:
                        continue
        return total

    # Binary search bounds
    low = 1
    high = k * min(n, m)  # Upper bound

    while low < high:
        mid = (low + high) // 2
        if count_up_to(mid) >= k:
            high = mid
        else:
            low = mid + 1

    print(low)

solve()
