        for j in range(n):
            if dp[i][j] == INF:
                continue

            # Feed hare i+1 from the left
            if i + 1 + j <= n:
                # Left adjacent: i (already fed), Right adjacent: i+2 (not fed)
                # One adjacent full, one adjacent hungry → gives b[i+1]
                if j == 0:
                    # Both adjacent are not fed (i and i+2 are not fed)
                    if i == 0:
                        dp[i+1][j] = max(dp[i+1][j], dp[i][j] + a[i+1])
