    order = [i for i in range(1, N * N + 1)]

    # Define move functions for each piece
    def knight_moves(r, c):
        moves = [] 
        dr = [-2, -2, -1, -1, 1, 1, 2, 2]
        dc = [-1, 1, -2, 2, -2, 2, -1, 1]
        for i in range(8):
            nr, nc = r + dr[i], c + dc[i]
            if 0 <= nr < N and 0 <= nc < N:
                moves.append((nr, nc))
        return moves

    def bishop_moves(r, c):
        moves = [] 
        for dr in [-1, 1]:
            for dc in [-1, 1]:
                r2, c2 = r + dr, c + dc
                while 0 <= r2 < N and 0 <= c2 < N:
                    moves.append((r2, c2))
                    r2 += dr
                    c2 += dc
        return moves

    def rook_moves(r, c):
        moves = [] 
        for dr in [-1, 1]:
            r2, c2 = r + dr, c
            while 0 <= r2 < N and 0 <= c2 < N:
                moves.append((r2, c2))
                r2 += dr
        for dc in [-1, 1]:
            r2, c2 = r, c + dc
            while 0 <= r2 < N and 0 <= c2 < N:
                moves.append((r2, c2))
                c2 += dc
        return moves

    # State: (position, piece_type, target_index) where piece_type is 0 for knight, 1 for bishop, 2 for rook
    # Cost is tuple: (steps, replacements)

    from heapq import heappush, heappop

