        n, x, y = map(int, input().split())

        # Find the optimal difference d
        # We want d to divide (y - x)
        # And we want the array to have both x and y

        # Try all possible divisors of (y - x)
        diff = y - x

        # Find the divisor that gives the minimum max element
        best_a1 = None
        best_d = None

        # Try divisors of diff (positive and negative)
        for d in range(1, diff + 1):
            if diff % d == 0:
                # Try starting at x - k*d for some k
                a1 = None
                for k in range(1, n):
                    a1_candidate = x - k*d
                    if a1_candidate > 0:
                        all_positive = True
                        for i in range(n):
                            if a1_candidate + i*d <= 0:
                                all_positive = False
                                break
                        if all_positive:
                            a1 = a1_candidate
                            break

