                    max_element = a1 + (n-1)*d
                    if best_a1 is None or max_element < (best_a1 + (n-1)*best_d):
                        best_a1 = a1
                        best_d = d

        result = [best_a1 + i*best_d for i in range(n)]
        results.append(result)

