    eggs = []
    for _ in range(n):
        a, g = map(int, input().split())
        eggs.append((a, g))

    # Try to balance the totals
    sa = 0  # Total paid to A
    sg = 0  # Total paid to G
    result = []

    # Try to give eggs to A if it helps balance the difference
    for a, g in eggs:
        if sa < sg - 500:
            # A is behind by more than 500, give to A to catch up
            sa += a
            result.append('A')
        elif sg < sa - 500:
            # G is behind by more than 500, give to G to catch up
            sg += g
            result.append('G')
        else:
            # Balance is within 500, just give to whichever is more expensive
            if a > g:
                sa += a
                result.append('A')
            else:
                sg += g
                result.append('G')

    # Check if the final condition is satisfied
    if abs(sa - sg) > 500:
        print(-1)
    else:
        print(''.join(result))

solve()
