    for i in range(len(sorted_letters) - 1):
        # Get first occurrence indices
        index1 = s.index(sorted_letters[i])
        index2 = s.index(sorted_letters[i+1])

        # Check if first occurrence of later letter comes after earlier one
        if index2 <= index1:
            valid = False
            break

print("YES" if valid else "NO")
