def solve() -> None:
    """Solve the problem."""
    import sys
    input = sys.stdin.read()
    data = input.strip().split()

    if not data:
        return

    n = int(data[0])
    x = int(data[1])
    a = list(map(int, data[2:2 + n]))

    seen = {}
    ans = 0

    for num in a:
        target = num ^ x
        if target in seen:
            ans += seen[target]
        if num in seen:
            seen[num] += 1
        else:
            seen[num] = 1

    print(ans)

if __name__ == "__main__":
    solve()
"}

