import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    total = sum(a)

    indices = []
    for i in range(n):
        if a[i] * n == total:
            indices.append(i + 1)  # Convert to 1-indexed

    print(len(indices))
    if indices:
        print(' '.join(map(str, indices)))

if __name__ == "__main__":
    solve()
"}

